}

.gn-slide-rail {
    overflow: hidden;
    box-sizing: content-box;
}

.gn-slide-rail * {
    box-sizing: content-box;
}

.gn-slide-rail .gn-slide-bar {
    position: absolute;
    background-color: #ffffff;
    background-position: center;
    background-repeat: no-repeat;
    cursor: pointer;
    left: 0;
    top: 0;
}

.gn-slide-rail .gn-slide-progress {
